package com.crm.customer;
import com.crm.customer.entity.Customer;import com.crm.customer.dto.CustomerRequest;import com.crm.customer.mapper.CustomerMapper;import com.crm.customer.repository.CustomerRepository;import com.crm.customer.service.impl.CustomerServiceImpl;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import java.util.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class CommercialIntegrityPolicyTest {CustomerRepository repository;CustomerServiceImpl service;Customer row;@BeforeEach void setup(){repository=mock(CustomerRepository.class);service=new CustomerServiceImpl(repository,new CustomerMapper());row=new Customer();row.setId(7L);row.setName("Kept");row.setContactType("LEAD");when(repository.lockById(7L)).thenReturn(Optional.of(row));}
 @Test void deleteArchivesWithoutRemovingContactOrHistoricalReferences(){service.deleteCustomer(7L);assertTrue(row.isArchived());verify(repository,never()).delete(any(Customer.class));verify(repository,never()).deleteById(any());service.deleteCustomer(7L);assertTrue(row.isArchived());}
 @Test void archivedContactsCannotBeEditedOrConverted(){row.setArchived(true);var r=new CustomerRequest();r.setName("Other");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateCustomer(7L,r));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.convertLead(7L));assertEquals("Kept",row.getName());verify(repository,never()).save(any());}
 @Test void restorePreservesIdentityAndAssignment(){row.setArchived(true);row.setAssignedEmployeeId(101L);var r=service.restore(7L);assertFalse(r.isArchived());assertEquals(7L,r.getId());assertEquals(101L,r.getAssignedEmployeeId());}
 @Test void advancedFiltersArePassedTogetherWithABoundedStablePage(){when(repository.findAll(any(Specification.class),any(Pageable.class))).thenReturn(new PageImpl<>(List.of(row)));service.search(2,25,"email","desc","acme","LEAD","Cat","Seg",101L,"ACTIVE");verify(repository).findAll(any(Specification.class),argThat((Pageable p)->p.getPageNumber()==2&&p.getPageSize()==25&&p.getSort().getOrderFor("email").isDescending()&&p.getSort().getOrderFor("id")!=null));verify(repository,never()).findAll();}
 @Test void invalidSortPaginationAndFiltersFailBeforeDatabase(){assertThrows(IllegalArgumentException.class,()->service.search(0,101,"name","asc",null,null,null,null,null,null));assertThrows(IllegalArgumentException.class,()->service.search(0,20,"password","asc",null,null,null,null,null,null));assertThrows(IllegalArgumentException.class,()->service.search(0,20,"name","asc",null,null,null,null,-1L,null));assertThrows(IllegalArgumentException.class,()->service.search(0,20,"name","asc",null,null,null,null,null,"INVALID"));verifyNoInteractions(repository);}
 @Test void missingArchiveTargetIsNotFabricated(){assertThrows(com.crm.customer.exception.ResourceNotFoundException.class,()->service.deleteCustomer(99L));verify(repository,never()).delete(any(Customer.class));} @Test void legacyArrayListIsBoundedWithoutSilentTruncation(){when(repository.findAll(any(Pageable.class))).thenReturn(new PageImpl<>(List.of(row),PageRequest.of(0,101),101));assertThrows(IllegalArgumentException.class,()->service.getAllCustomers());verify(repository,never()).findAll();}
}
